var connections = global.get('parat_bridge.connections') || {};
msg = {
    topic: 'connections/update',
    payload: connections
};
return msg;

const ctx = msg.error_context || {};
if (!ctx.notify_users || !ctx.connection_name) return null;
// Cascade-vern: dropp hvis entry_id starter med pb-err-
if (ctx.entry_id && ctx.entry_id.startsWith('pb-err-')) return null;

const cb = global.get('parat_bridge.circuit_breaker') || {};
const now = Date.now();

const connections = global.get('parat_bridge.connections') || {};
const conn = connections[ctx.connection_name];
if (!conn) return null;

const recipients = Object.values(conn.clients)
    .filter(client => client.client_system !== ctx.target_client_system)
    .filter(client => {
        const cbKey = ctx.connection_name + '::' + client.identifier;
        const cbEntry = cb[cbKey] || {};
        if (cbEntry.last_notified && (now - cbEntry.last_notified) < 5 * 60 * 1000) return false;
        cb[cbKey] = { last_notified: now };
        return true;
    })
    .map(client => ({
        topic: 'new_message',
        entry: {
            id: 'pb-err-' + now + '-' + Math.random().toString(36).slice(2, 7),
            text: ctx.user_message,
            timestamp: now,
            author: 'System-melding',
            files: [],
            labels: [],
            metadata: {
                source: { client_system: 'parat_bridge', name: 'parat_bridge', identifier: 'parat_bridge' },
                target: client,
                connection_name: ctx.connection_name,
            }
        }
    }));

global.set('parat_bridge.circuit_breaker', cb);
return recipients.length > 0 ? recipients : null;

const ctx = msg.error_context || {};
const code = ctx.statusCode;

let type, severity, userMessage;

if (!code) {
    type = 'network';
    severity = 'critical';
    userMessage = '⚠️ Forbindelsen er midlertidig nede. Meldinger vil ikke leveres før forbindelsen er gjenopprettet.';
} else if (code === 401 || code === 403) {
    type = 'auth';
    severity = 'critical';
    userMessage = '⚠️ Autentisering feilet. Kontakt administrator. Vennligst prøv å send meldingen på nytt når tilkobling er gjennopprettet';
} else if (code >= 500) {
    type = 'server';
    severity = 'critical';
    userMessage = '⚠️ Ekstern tjeneste svarer ikke. Meldinger vil ikke leveres før tjenesten er tilgjengelig igjen.';
} else if (code === 404) {
    type = 'not_found'; severity = 'warning'; userMessage = null;
} else if (code === 429) {
    type = 'rate_limit'; severity = 'warning'; userMessage = null;
} else if (code >= 400) {
    type = 'client'; severity = 'warning'; userMessage = null;
} else {
    type = 'unknown'; severity = 'warning'; userMessage = null;
}

msg.error_context = Object.assign({}, ctx, {
    type,
    severity,
    message: type === 'network' ? 'Nettverksfeil' : `HTTP ${code}`,
    notify_users: !!(userMessage && ctx.connection_name),
    user_message: userMessage
});

return msg;

const log = global.get('parat_bridge.error_log') || [];
const ctx = msg.error_context;
const THROTTLE_MS = 5 * 60 * 1000;
const now = Date.now();

const lastSimilar = log.find(e =>
    e.connection_name === ctx.connection_name &&
    e.type === ctx.type
);

if (lastSimilar && lastSimilar.timestamp) {
    const age = now - new Date(lastSimilar.timestamp).getTime();
    if (age < THROTTLE_MS) return msg;
}

log.unshift(ctx);
if (log.length > 100) log.length = 100;
global.set('parat_bridge.error_log', log);
return msg;

global.set('utils', {

    build_connection_name: (clients) => {
        return [...clients]
            .sort((a, b) => a.client_system.localeCompare(b.client_system))
            .map(c => `${c.client_system}-${c.identifier}`)
            .join("_");
    },

    build_label: (client) => {
        const colors = {
            wasos:        "#1f871f",
            rayvn:        "#000000",
            parat_bridge: "#b80d18"
        };
        return {
            id:       client.identifier,
            name:     `[${client.client_system}]: ${client.name}`,
            colorHex: colors[client.client_system] || "#888888"
        };
    },

    build_callsign: (client) => `[${client.client_system}:${client.name}]`,

    FILE_REASONS: {
        OVERSIZED:        "oversized",
        NON_TRANSFERABLE: "non_transferable",
        DOWNLOAD_FAILED:  "download_failed",
        UPLOAD_FAILED:    "upload_failed",
        COMPRESS_FAILED: "compress_failed"
    },

    is_compressible: (mime_type) => {
        if (!mime_type) return false;
        return ['video/', 'audio/', 'image/'].some(prefix => mime_type.startsWith(prefix));
    },

    get_mime_type: (filename) => {
        const ext = (filename || "").split('.').pop().toLowerCase();
        const types = {
            jpg: "image/jpeg", jpeg: "image/jpeg", png: "image/png",
            gif: "image/gif", webp: "image/webp", bmp: "image/bmp",
            svg: "image/svg+xml", heic: "image/heic",
            pdf: "application/pdf",
            mp4: "video/mp4", mov: "video/quicktime", avi: "video/x-msvideo",
            mp3: "audio/mpeg", wav: "audio/wav",
            doc: "application/msword", txt: "text/plain", csv: "text/csv",
            docx: "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
            xlsx: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
            zip: "application/zip"
        };
        return types[ext] || null;
    },  

    build_file_key: (message_id, connection_name, filename) => {
        const safe = filename.replace(/[\\\/\:*?"<>|]/g, "_");
        return message_id + "---" + connection_name + "---" + safe;
    },

    parse_file_key: (key) => {
        const raw   = key.startsWith("files.") ? key.slice("files.".length) : key;
        const parts = raw.split("---");
        return {
            message_id:      parts[0]              || null,
            connection_name: parts[1]              || null,
            filename:        parts.slice(2).join("---") || null
        };
    },

    is_bridge_message: (text) => {
        return /\[(?:wasos|rayvn|cim|parat_bridge)(?::|])/.test(text);
    },

    get_system_attributes: (system) => {
        const attributes = {
            rayvn: {
                max_upload_bytes: 1048576, // 1 MB
                can_upload: true,
                can_download: true
            },
            wasos: {
                max_upload_bytes: 1048576, // 10 MB (not a client restriction)
                can_upload: true,
                can_download: true
            },
            cim: {
                max_upload_bytes: null,
                can_upload: false,
                can_download: false
            }
        };
        return attributes[system] || null;
    }

});

return msg;

// Initialize context — sets runtime config only
// Connections and queue are already in cache (loaded by context store on open)
const pb = global.get("parat_bridge") || {};
pb.base_urls = {
    rayvn: "https://api.rayvn.global",
    wasos: "https://dev.wasos.no"
};
if (!pb.queue) pb.queue = { in_flight_connections: [], entry_queue: [] };
pb.queue.in_flight_connections = [];  // always reset on startup
if (!pb.circuit_breaker) pb.circuit_breaker = {};
global.set("parat_bridge", pb);
const conns = Object.keys(global.get("parat_bridge.connections") || {}).length;
const queue = (global.get("parat_bridge.queue.entry_queue") || []).length;
node.log("Active: " + conns + " connection(s), " + queue + " queued entries");
return msg;

const connections = global.get("parat_bridge.connections");

if (!connections) {
    msg.payload = [];
    return msg;
}


msg.payload = Object.values(connections).map(conn => {
    const clients = Object.values(conn.clients);
    return {
        "Klient 1": `${clients[0].client_system} — ${clients[0].name}`,
        "Klient 2": `${clients[1].client_system} — ${clients[1].name}`,
        status:     conn.active ? "🟢 aktiv" : "🔴 inaktiv",
        created:    new Date(conn.time_created).toLocaleString()
    };
});


return msg;

let errorLog = global.get('error_log') || [];

// Vis de siste 10 feilene, nyeste først
const recent = errorLog.slice(-10).reverse();

msg.payload = recent.map(e => ({
    time: e.timestamp.replace('T', ' ').substring(0, 19),
    type: e.type.toUpperCase(),
    source: e.source,
    status: e.statusCode || 'none',
    message: e.message.substring(0, 60)
}));

return msg;

/**
 * Build a user-facing notification about file transfer failures.
 * Groups failed files by reason and builds one combined message.
 */
const utils = global.get("utils");
const event = msg.payload;

const groups = {};
for (const f of (event.failed_files || [])) {
    if (!groups[f.reason]) groups[f.reason] = [];
    groups[f.reason].push(f.name);
}

const lines = [];

if (groups[utils.FILE_REASONS.OVERSIZED]) {
    lines.push("⚠️ " + groups[utils.FILE_REASONS.OVERSIZED].length
        + " vedlegg for store for mottakersystemet (maks 1 MB): "
        + groups[utils.FILE_REASONS.OVERSIZED].join(", ") + ".");
}

if (groups[utils.FILE_REASONS.NON_TRANSFERABLE]) {
    lines.push("⚠️ " + groups[utils.FILE_REASONS.NON_TRANSFERABLE].length
        + " vedlegg kan ikke overføres automatisk. "
        + "Tips: Høyreklikk på vedlegg → «Kopier adresse» → lim inn adressen som tekst.");
}

if (groups[utils.FILE_REASONS.DOWNLOAD_FAILED]) {
    lines.push("⚠️ " + groups[utils.FILE_REASONS.DOWNLOAD_FAILED].length
        + " vedlegg kunne ikke lastes ned fra kildesystemet: "
        + groups[utils.FILE_REASONS.DOWNLOAD_FAILED].join(", ") + ".");
}

if (groups[utils.FILE_REASONS.UPLOAD_FAILED]) {
    lines.push("⚠️ " + groups[utils.FILE_REASONS.UPLOAD_FAILED].length
        + " vedlegg ble avvist av mottakersystemet: "
        + groups[utils.FILE_REASONS.UPLOAD_FAILED].join(", ") + ".");
}

if (lines.length === 0) return null;

msg._notification_text = lines.join(" ");
msg._event = event;

return msg;

/**
 * Wrap the notification text in a bridge entry format
 * that can be sent through the queue to the sender's system.
 *
 * The entry is addressed FROM parat_bridge TO the sender.
 * This means it goes to the same system the sender used,
 * so they see the notification in their own interface.
 *
 * client_system is set to 'parat_bridge' so the Filter subflow
 * recognises and drops it when polled back, preventing loops.
 *
 * Returns a clean object — no inherited properties.
 */
const event    = msg._event;
const metadata = event.metadata;
const now      = Date.now();

return {
    topic: "new_message",
    entry: {
        id:        "pb-att-" + now + "-" + Math.random().toString(36).substr(2, 6),
        text:      msg._notification_text,
        timestamp: now,
        author:    "System-melding",
        labels:    [],
        metadata: {
            source: {
                client_system: "parat_bridge",
                name:          "parat_bridge",
                identifier:    "parat_bridge"
            },
            target:          metadata.source,
            connection_name: metadata.connection_name,
            files: null
        }
    }
};

const connection_name = (msg.metadata && msg.metadata.connection_name)
    || (msg.entry && msg.entry.metadata && msg.entry.metadata.connection_name)
    || null;

// GET-feil: ingen entry, men metadata.source finnes
if (!msg.entry && msg.metadata && msg.metadata.source) {
    const sourceId = msg.metadata.source.identifier;
    if (connection_name && sourceId) {
        const connections = global.get('parat_bridge.connections') || {};
        const conn = connections[connection_name];
        if (conn) {
            conn.source_status = conn.source_status || {};
            conn.source_status[sourceId] = conn.source_status[sourceId]
                || { consecutive_failures: 0, down: false };
            conn.source_status[sourceId].consecutive_failures++;
            const THRESHOLD = 3;
            if (conn.source_status[sourceId].consecutive_failures >= THRESHOLD
                && !conn.source_status[sourceId].down) {
                conn.source_status[sourceId].down = true;
                const entryQueue = global.get('parat_bridge.queue.entry_queue') || [];
                const now = Date.now();
                const sourceName = msg.metadata.source.name || sourceId;
                Object.values(conn.clients || {})
                    .filter(c => c.identifier !== sourceId)
                    .forEach((client, idx) => {
                        entryQueue.push({
                            entry: {
                                id: 'pb-err-' + (now + idx) + '-src-down-'
                                    + Math.random().toString(36).slice(2, 5),
                                text: '⚠️ Tilkoblingen til ' + sourceName
                                    + ' er nede. Meldinger kan ikke mottas.',
                                timestamp: now + idx,
                                author: 'System-melding',
                                files: [], labels: [],
                                metadata: {
                                    source: {
                                        client_system: 'parat_bridge',
                                        name: 'parat_bridge', identifier: 'parat_bridge'
                                    },
                                    target: client,
                                    connection_name: connection_name
                                }
                            },
                            _retries: 0
                        });
                    });
                global.set('parat_bridge.queue.entry_queue', entryQueue);
                node.log('Source down: ' + sourceName + ' (' + sourceId + ') - notified ' + connection_name);
            }
            global.set('parat_bridge.connections.' + connection_name, conn);
        }
    }
    msg.error_context = {
        timestamp: new Date().toISOString(),
        source: msg.error && msg.error.source ? msg.error.source.name : 'unknown',
        raw_message: msg.error ? msg.error.message : null,
        statusCode: msg.statusCode || null,
        connection_name: connection_name,
        entry_id: null,
        target_client_system: null,
        direction: 'inbound'
    };
    return msg;
}

try {
    if (connection_name) {
        const queue = global.get('parat_bridge.queue') || {};
        const inFlight = (queue.in_flight_connections || []).filter(n => n !== connection_name);
        global.set('parat_bridge.queue.in_flight_connections', inFlight);
        const entryQueue = queue.entry_queue || [];
        const entry_id = msg.entry && msg.entry.id;
        if (entry_id) {
            const idx = entryQueue.findIndex(e => e.entry.id === entry_id);
            if (idx !== -1) {
                entryQueue[idx]._retries = (entryQueue[idx]._retries || 0) + 1;
                if (entryQueue[idx]._retries >= 10) {
                    let filtered;
                    if (entry_id && entry_id.startsWith('pb-err-')) {
                        filtered = entryQueue.filter(e => e.entry.id !== entry_id);
                    } else {
                        const toBeFailed = entryQueue.filter(e =>
                            e.entry.metadata &&
                            e.entry.metadata.connection_name === connection_name &&
                            !(e.entry.id && e.entry.id.startsWith('pb-err-'))
                        );
                        if (toBeFailed.length > 0) {
                            const connections = global.get('parat_bridge.connections') || {};
                            const conn = connections[connection_name];
                            if (conn) {
                                conn.failed_entries = conn.failed_entries || {};
                                conn.status = conn.status || {};
                                conn.status.failed_clients = conn.status.failed_clients || [];
                                toBeFailed.forEach(e => {
                                    const targetId = e.entry.metadata &&
                                        e.entry.metadata.target &&
                                        e.entry.metadata.target.identifier;
                                    if (targetId) {
                                        conn.failed_entries[targetId] = (conn.failed_entries[targetId] || [])
                                            .concat([e.entry]);
                                        if (!conn.status.failed_clients.includes(targetId)) {
                                            conn.status.failed_clients.push(targetId);
                                        }
                                    }
                                });
                                global.set('parat_bridge.connections.' + connection_name, conn);
                            }
                        }
                        filtered = entryQueue.filter(e =>
                            !(e.entry.metadata && e.entry.metadata.connection_name === connection_name) ||
                            (e.entry.id && e.entry.id.startsWith('pb-err-'))
                        );
                    }
                    global.set('parat_bridge.queue.entry_queue', filtered);
                } else {
                    global.set('parat_bridge.queue.entry_queue', entryQueue);
                }
            }
        }
    }
} catch (e) {
    try {
        const queue = global.get('parat_bridge.queue') || {};
        const inFlight = (queue.in_flight_connections || []).filter(n => n !== connection_name);
        global.set('parat_bridge.queue.in_flight_connections', inFlight);
    } catch (_) { }
    node.warn('ErrorObject cleanup failed: ' + e.message);
}
msg.error_context = {
    timestamp: new Date().toISOString(),
    source: msg.error && msg.error.source ? msg.error.source.name : 'unknown',
    raw_message: msg.error ? msg.error.message : null,
    statusCode: msg.statusCode || null,
    connection_name: connection_name,
    entry_id: (msg.entry && msg.entry.id) || null,
    target_client_system: (msg.entry && msg.entry.metadata && msg.entry.metadata.target && msg.entry.metadata.target.client_system) || null,
    direction: 'unknown'
};
return msg;

const entry = msg.entry || {};
const metadata = entry.metadata || {};
const target = metadata.target || {};
const connection_name = metadata.connection_name || null;
// Cascade-vern — pb-entries skal ikke lagres i failed_entries
if (entry.id && entry.id.startsWith('pb-')) {
    msg.error_context = {
        timestamp: new Date().toISOString(),
        source: target.client_system ? 'POST to ' + target.client_system : 'POST entries',
        raw_message: null,
        statusCode: msg.statusCode || null,
        connection_name: connection_name,
        entry_id: entry.id || null,
        target_client_system: target.client_system || null,
        direction: 'outbound'
    };
    return msg;
}
if (connection_name && entry.id) {
    const connections = global.get('parat_bridge.connections') || {};
    const conn = connections[connection_name];
    const targetId = target.identifier || null;
    if (conn && targetId) {
        conn.failed_entries = conn.failed_entries || {};
        // Lagre current entry (med dedup — Retry-noden kan allerede ha lagret den
        // tilbake til failed_entries hvis dette er en _recovery-entry som traff MAX_RETRIES)
        const entryToSave = { ...entry };
        delete entryToSave._recovery;
        conn.failed_entries[targetId] = conn.failed_entries[targetId] || [];
        if (!conn.failed_entries[targetId].some(e => e.id === entryToSave.id)) {
            conn.failed_entries[targetId] = conn.failed_entries[targetId].concat([entryToSave]);
        }
        if (!conn.status.failed_clients.includes(targetId)) {
            conn.status.failed_clients.push(targetId);
        }
        // Circuit breaker: tøm alle ventende entries for samme target fra køen
        const entryQueue = global.get('parat_bridge.queue.entry_queue') || [];
        const pending = entryQueue.filter(e =>
            e.entry.metadata &&
            e.entry.metadata.connection_name === connection_name &&
            e.entry.metadata.target &&
            e.entry.metadata.target.identifier === targetId &&
            !(e.entry.id && e.entry.id.startsWith('pb-')) &&
            !e.entry._recovery &&
            e.entry.id !== entry.id
        );
        if (pending.length > 0) {
            pending.forEach(e => {
                const toSave = { ...e.entry };
                delete toSave._recovery;
                conn.failed_entries[targetId].push(toSave);
            });
            const pendingIds = new Set(pending.map(e => e.entry.id));
            global.set('parat_bridge.queue.entry_queue',
                entryQueue.filter(e => !pendingIds.has(e.entry.id) && e.entry.id !== entry.id));
            node.log('Circuit breaker: drained ' + pending.length +
                ' pending entries for ' + targetId);
        } else {
            global.set('parat_bridge.queue.entry_queue',
                entryQueue.filter(e => e.entry.id !== entry.id));
        }
        global.set('parat_bridge.connections.' + connection_name, conn);
    }
}
msg.error_context = {
    timestamp: new Date().toISOString(),
    source: target.client_system ? 'POST to ' + target.client_system : 'POST entries',
    raw_message: null,
    statusCode: msg.statusCode || null,
    connection_name: connection_name,
    entry_id: entry.id || null,
    target_client_system: target.client_system || null,
    direction: 'outbound'
};
return msg;

msg.error_context = {
    timestamp: new Date().toISOString(),
    source: msg.error && msg.error.source ? msg.error.source.name : 'unknown',
    raw_message: msg.error ? msg.error.message : null,
    statusCode: msg.statusCode || null,
    connection_name: (msg.metadata && msg.metadata.connection_name) || null,
    entry_id: null,
    target_client_system: null,
    direction: 'inbound'
};
return msg;
